// Integration + wireless IPC handlers — thin delegation to IntegrationManager,
// WirelessManager, and DeviceManager.

import { ipcMain } from "@glaze/core/backend";

import { deviceManager } from "../services/device-manager.js";
import { integrationManager } from "../services/integration-manager.js";
import { wirelessManager } from "../services/wireless-manager.js";

export function registerIntegrationHandlers(): void {
  ipcMain.handle("integrations:list", async () => {
    return {
      descriptors: integrationManager.getDescriptors(),
      states: integrationManager.getStates(),
    };
  });

  ipcMain.handle(
    "integrations:setConfig",
    async (_event: unknown, params: unknown) => {
      const { id, config } = params as {
        id: string;
        config: Record<string, unknown>;
      };
      if (typeof id !== "string" || !id) {
        throw new Error("integrations:setConfig — id (string) required");
      }
      if (typeof config !== "object" || config === null) {
        throw new Error("integrations:setConfig — config (object) required");
      }
      return integrationManager.setConfig(id, config);
    },
  );

  ipcMain.handle(
    "integrations:setEnabled",
    async (_event: unknown, params: unknown) => {
      const { id, enabled } = params as { id: string; enabled: boolean };
      if (typeof id !== "string" || !id) {
        throw new Error("integrations:setEnabled — id (string) required");
      }
      if (typeof enabled !== "boolean") {
        throw new Error("integrations:setEnabled — enabled (boolean) required");
      }
      return integrationManager.setEnabled(id, enabled);
    },
  );

  ipcMain.handle(
    "integrations:test",
    async (_event: unknown, params: unknown) => {
      const { id } = params as { id: string };
      if (typeof id !== "string" || !id) {
        throw new Error("integrations:test — id (string) required");
      }
      return integrationManager.test(id);
    },
  );

  // ── Wireless connections (multi-connection API) ────────────────────────

  ipcMain.handle("wireless:listProviders", async () => {
    return wirelessManager.listProviders();
  });

  ipcMain.handle("wireless:listConnections", async () => {
    return wirelessManager.listConnections();
  });

  ipcMain.handle("wireless:addConnection", async (_event: unknown, params: unknown) => {
    const p = (params ?? {}) as Record<string, unknown>;
    const name = typeof p.name === "string" ? p.name : undefined;
    const providerId = typeof p.providerId === "string" ? p.providerId : undefined;
    return wirelessManager.addConnection({ name, providerId });
  });

  ipcMain.handle("wireless:updateConnection", async (_event: unknown, params: unknown) => {
    const p = params as Record<string, unknown>;
    if (typeof p.id !== "string" || !p.id) {
      throw new Error("wireless:updateConnection — id (string) required");
    }
    const rawPatch = (p.patch ?? {}) as Record<string, unknown>;
    const patch: {
      name?: string;
      providerId?: string;
      enabled?: boolean;
      config?: Record<string, unknown>;
    } = {};
    if (typeof rawPatch.name === "string") patch.name = rawPatch.name;
    if (typeof rawPatch.providerId === "string") patch.providerId = rawPatch.providerId;
    if (typeof rawPatch.enabled === "boolean") patch.enabled = rawPatch.enabled;
    if (typeof rawPatch.config === "object" && rawPatch.config !== null) {
      patch.config = rawPatch.config as Record<string, unknown>;
    }
    return wirelessManager.updateConnection({ id: p.id, patch });
  });

  ipcMain.handle("wireless:removeConnection", async (_event: unknown, params: unknown) => {
    const p = params as Record<string, unknown>;
    if (typeof p.id !== "string" || !p.id) {
      throw new Error("wireless:removeConnection — id (string) required");
    }
    return wirelessManager.removeConnection({ id: p.id });
  });

  ipcMain.handle("wireless:testConnection", async (_event: unknown, params: unknown) => {
    const p = params as Record<string, unknown>;
    if (typeof p.id !== "string" || !p.id) {
      throw new Error("wireless:testConnection — id (string) required");
    }
    return wirelessManager.testConnection({ id: p.id });
  });

  ipcMain.handle("wireless:listChannels", async () => {
    return deviceManager.listChannels();
  });

  ipcMain.handle("wireless:getMeterRate", async () => {
    return { ms: wirelessManager.getMeterRate() };
  });

  ipcMain.handle("wireless:setMeterRate", async (_event: unknown, params: unknown) => {
    const p = params as Record<string, unknown>;
    if (typeof p.ms !== "number" || !Number.isFinite(p.ms) || p.ms < 0) {
      throw new Error("wireless:setMeterRate — ms (non-negative number) required");
    }
    return wirelessManager.setMeterRate(p.ms);
  });
}
