// Stage IPC handlers — thin delegation to StageController.

import { ipcMain } from "@glaze/core/backend";

import type { Slot } from "../types/stage.js";
import { openDisplayWindow } from "../windows/display-windows.js";
import { remoteServer } from "../services/remote-server.js";
import { stageController } from "../services/stage-controller.js";

export function registerStageHandlers(): void {
  ipcMain.handle("stage:getState", async () => {
    return stageController.getState();
  });

  ipcMain.handle("stage:listServiceTypes", async () => {
    return stageController.listServiceTypes();
  });

  ipcMain.handle(
    "stage:listPlans",
    async (_event: unknown, params: unknown) => {
      const { serviceTypeId } = params as { serviceTypeId: string };
      if (typeof serviceTypeId !== "string" || !serviceTypeId) {
        throw new Error("stage:listPlans — serviceTypeId (string) required");
      }
      return stageController.listPlans(serviceTypeId);
    },
  );

  ipcMain.handle(
    "stage:setServiceType",
    async (_event: unknown, params: unknown) => {
      const { id } = params as { id: string };
      if (typeof id !== "string" || !id) {
        throw new Error("stage:setServiceType — id (string) required");
      }
      return stageController.setServiceType(id);
    },
  );

  ipcMain.handle(
    "stage:setPlan",
    async (_event: unknown, params: unknown) => {
      const { id } = params as { id: string };
      if (typeof id !== "string" || !id) {
        throw new Error("stage:setPlan — id (string) required");
      }
      return stageController.setPlan(id);
    },
  );

  ipcMain.handle("stage:selectNextPlan", async () => {
    return stageController.selectNextPlan();
  });

  ipcMain.handle(
    "stage:setPlanMode",
    async (_event: unknown, params: unknown) => {
      const { mode } = params as { mode: "auto" | "manual" };
      if (mode !== "auto" && mode !== "manual") {
        throw new Error('stage:setPlanMode — mode must be "auto" or "manual"');
      }
      return stageController.setPlanMode(mode);
    },
  );

  ipcMain.handle(
    "stage:setSlots",
    async (_event: unknown, params: unknown) => {
      const p = params as { displayId?: string; slots: Slot[] };
      if (!Array.isArray(p?.slots)) {
        throw new Error("stage:setSlots — slots (array) required");
      }
      return stageController.setSlots(p.displayId ?? "", p.slots);
    },
  );

  ipcMain.handle("stage:refresh", async () => {
    return stageController.refresh();
  });

  ipcMain.handle(
    "stage:setAllowedServiceTypes",
    async (_event: unknown, params: unknown) => {
      const p = params as { ids: unknown };
      if (!Array.isArray(p?.ids) || !p.ids.every((id) => typeof id === "string")) {
        throw new Error("stage:setAllowedServiceTypes — ids (string[]) required");
      }
      return stageController.setAllowedServiceTypes(p.ids as string[]);
    },
  );

  ipcMain.handle("stage:getRemoteUrl", async () => {
    return { url: remoteServer.getLanUrl() };
  });

  ipcMain.handle(
    "stage:setShowQr",
    async (_event: unknown, params: unknown) => {
      const { show } = params as { show: boolean };
      if (typeof show !== "boolean") {
        throw new Error("stage:setShowQr — show (boolean) required");
      }
      return stageController.setShowQr(show);
    },
  );

  ipcMain.handle("presets:list", async () => {
    return stageController.listPresets();
  });

  ipcMain.handle(
    "presets:save",
    async (_event: unknown, params: unknown) => {
      const p = params as { displayId?: string; name: string };
      if (typeof p?.name !== "string" || !p.name.trim()) {
        throw new Error("presets:save — name (non-empty string) required");
      }
      return stageController.savePreset(p.displayId ?? "", p.name.trim());
    },
  );

  ipcMain.handle(
    "presets:apply",
    async (_event: unknown, params: unknown) => {
      const p = params as { displayId?: string; id: string };
      if (typeof p?.id !== "string" || !p.id) {
        throw new Error("presets:apply — id (string) required");
      }
      return stageController.applyPreset(p.displayId ?? "", p.id);
    },
  );

  ipcMain.handle(
    "presets:delete",
    async (_event: unknown, params: unknown) => {
      const { id } = params as { id: string };
      if (typeof id !== "string" || !id) {
        throw new Error("presets:delete — id (string) required");
      }
      return stageController.deletePreset(id);
    },
  );

  // ── Display management ────────────────────────────────────────────────

  ipcMain.handle(
    "displays:add",
    async (_event: unknown, params: unknown) => {
      const p = params as { name?: string } | undefined;
      const name = typeof p?.name === "string" ? p.name : undefined;
      const state = await stageController.addDisplay(name);
      // Auto-open a window for the newly-added display.
      const newDisplay = state.displays[state.displays.length - 1];
      if (newDisplay) {
        openDisplayWindow(newDisplay).catch((err) => {
          console.error(`[displays:add] failed to open window for ${newDisplay.id}:`, err);
        });
      }
      return state;
    },
  );

  ipcMain.handle(
    "displays:rename",
    async (_event: unknown, params: unknown) => {
      const p = params as { id: string; name: string };
      if (typeof p?.id !== "string" || !p.id) {
        throw new Error("displays:rename — id (string) required");
      }
      if (typeof p?.name !== "string" || !p.name.trim()) {
        throw new Error("displays:rename — name (non-empty string) required");
      }
      return stageController.renameDisplay(p.id, p.name);
    },
  );

  ipcMain.handle(
    "displays:remove",
    async (_event: unknown, params: unknown) => {
      const p = params as { id: string };
      if (typeof p?.id !== "string" || !p.id) {
        throw new Error("displays:remove — id (string) required");
      }
      const state = await stageController.removeDisplay(p.id);
      // Close the window for the removed display (imported lazily to avoid circular deps).
      const { closeDisplayWindow } = await import("../windows/display-windows.js");
      closeDisplayWindow(p.id);
      return state;
    },
  );

  ipcMain.handle(
    "displays:openWindow",
    async (_event: unknown, params: unknown) => {
      const p = params as { id: string };
      if (typeof p?.id !== "string" || !p.id) {
        throw new Error("displays:openWindow — id (string) required");
      }
      const display = stageController.getDisplays().find((d) => d.id === p.id);
      if (!display) throw new Error(`displays:openWindow — display ${p.id} not found`);
      await openDisplayWindow(display);
      return { ok: true };
    },
  );
}
