// Creates and manages per-display kiosk windows.
// Each display gets a stable BrowserWindow keyed by "display-<id>".

import { BrowserWindow, logger } from "@glaze/core/backend";

import type { DisplayInfo } from "../types/stage.js";
import { getPreloadPath, getWindowUrl } from "./window-paths.js";

// Map of displayId → BrowserWindow.
const displayWindows = new Map<string, BrowserWindow>();

/**
 * Open (or focus if already open) a kiosk window for the given display.
 * The window loads main-window.html?display=<id> so the renderer knows which
 * display it belongs to.
 */
export async function openDisplayWindow(display: DisplayInfo): Promise<BrowserWindow> {
  const existing = displayWindows.get(display.id);
  if (existing && !existing.isDestroyed()) {
    logger.debug("display-windows", `Focusing existing window for display ${display.id}`);
    existing.show();
    existing.focus();
    return existing;
  }

  logger.info("display-windows", `Creating window for display ${display.id} ("${display.name}")`);

  const win = new BrowserWindow({
    windowKey: `display-${display.id}`,
    width: 1000,
    height: 700,
    minWidth: 390,
    minHeight: 456,
    title: `Stage Monitor — ${display.name}`,
    show: false,
    webPreferences: {
      preload: getPreloadPath(),
    },
  });

  win.once("ready-to-show", () => {
    win.show();
  });

  win.on("closed", () => {
    displayWindows.delete(display.id);
    logger.debug("display-windows", `Window closed for display ${display.id}`);
  });

  const baseUrl = await getWindowUrl("main-window.html");
  const url = `${baseUrl}${baseUrl.includes("?") ? "&" : "?"}display=${encodeURIComponent(display.id)}`;

  logger.info("display-windows", `Loading URL for display ${display.id}`, { url });
  await win.loadURL(url);

  displayWindows.set(display.id, win);
  return win;
}

/**
 * Close the window for a display, if it exists.
 */
export function closeDisplayWindow(displayId: string): void {
  const win = displayWindows.get(displayId);
  if (win && !win.isDestroyed()) {
    logger.info("display-windows", `Closing window for display ${displayId}`);
    win.close();
  }
  displayWindows.delete(displayId);
}

/**
 * Close all display windows. Called from before-quit.
 */
export function closeAllDisplayWindows(): void {
  logger.info("display-windows", `Closing all ${displayWindows.size} display window(s)`);
  for (const [id, win] of displayWindows.entries()) {
    if (!win.isDestroyed()) {
      win.close();
    }
    displayWindows.delete(id);
  }
}

/**
 * Return the BrowserWindow for a given displayId, or null if it doesn't exist.
 */
export function getDisplayWindow(displayId: string): BrowserWindow | null {
  const win = displayWindows.get(displayId);
  return win && !win.isDestroyed() ? win : null;
}
