// Main process entry point - Node.js backend for Glaze app
//
// The glaze CLI runtime automatically handles all framework wiring (IPC server,
// native bridge, lifecycle, signal handlers) before this file runs.
// This entry point uses only APIs.

import { app, Menu, logger, initDevToolsButtonState, protocol } from "@glaze/core/backend";

import { registerHandlers } from "./handlers/index.js";
import { openSettingsWindow } from "./windows/settings-window.js";
import { openDisplayWindow, closeAllDisplayWindows } from "./windows/display-windows.js";
import { deviceManager } from "./services/device-manager.js";
import { integrationManager } from "./services/integration-manager.js";
import { getPhotoPath } from "./services/photo-cache.js";
import { remoteServer } from "./services/remote-server.js";
import { stageController } from "./services/stage-controller.js";

// ── stage-photo protocol — register BEFORE any BrowserWindow is created ──
// The scheme must be registered early; a full relaunch is required when adding
// a new scheme for the first time.
protocol.registerSchemesAsPrivileged([
  {
    scheme: "stage-photo",
    privileges: { standard: true, secure: true, supportFetchAPI: true, stream: true },
  },
]);

// ── IPC Handlers ──────────────────────────────────────────────────────
// ipcMain is already wired to the IPC server by the runtime bootstrap.
registerHandlers();

// ── Window creation ───────────────────────────────────────────────────

/** Open one kiosk window per display currently in stage state. */
async function openAllDisplayWindows(): Promise<void> {
  const displays = stageController.getDisplays();
  logger.info("main", `⏱️ [COLD_START] Opening ${displays.length} display window(s)`);
  for (const display of displays) {
    try {
      await openDisplayWindow(display);
    } catch (err) {
      logger.error("main", `Failed to open window for display ${display.id}`, err);
    }
  }
}

// ── Application menu ──────────────────────────────────────────────────
async function setupApplicationMenu() {
  await initDevToolsButtonState();
  const menu = Menu.buildFromTemplate([
    {
      label: "App",
      submenu: [
        { role: "about" },
        { type: "separator" },
        {
          label: "Settings…",
          icon: "gearshape",
          accelerator: "Command+,",
          click: async () => await openSettingsWindow(),
        },
        { type: "separator" },
        { role: "services" },
        { type: "separator" },
        { role: "hide" },
        { role: "hideOthers" },
        { role: "unhide" },
        { type: "separator" },
        { role: "quit" },
      ],
    },
    { role: "fileMenu" },
    { role: "editMenu" },
    { role: "viewMenu" },
    { role: "windowMenu" },
  ]);
  Menu.setApplicationMenu(menu);
  logger.info("main", "Application menu configured with Settings");
}

// ── Lifecycle events ──────────────────────────────────────────────────
app.on("window-all-closed", () => {
  // On macOS, apps typically don't quit when all windows are closed
  // Uncomment to quit on all windows closed:
  // app.quit();
});

app.on("activate", (hasVisibleWindows) => {
  logger.info("main", "App activate event received", { hasVisibleWindows });
  // On macOS, re-open display windows when dock icon clicked if no windows visible.
  if (!hasVisibleWindows) {
    openAllDisplayWindows().catch((err) => {
      logger.error("main", "Failed to re-open display windows on activate", err);
    });
  }
});

app.on("before-quit", () => {
  logger.info("main", "App before-quit, cleaning up...");
  // Close all display windows, stop the hourly plan refresh, LAN HTTP server, and wireless device manager.
  closeAllDisplayWindows();
  stageController.stopAutoRefresh();
  remoteServer.stop().catch((err) => logger.error("main", "remoteServer stop error", err));
  deviceManager.stop().catch((err) => logger.error("main", "deviceManager stop error", err));
});

// ── App ready ─────────────────────────────────────────────────────────
const startTime = Date.now();
logger.info("main", "⏱️ [COLD_START] Waiting for app ready...", {
  timestamp: new Date().toISOString(),
});

app.whenReady().then(async () => {
  const windowCreateStartTime = Date.now();
  logger.info("main", "⏱️ [COLD_START] App ready, creating main window", {
    timestamp: new Date().toISOString(),
    wait_duration_ms: windowCreateStartTime - startTime,
  });

  // ── stage-photo protocol handler ────────────────────────────────────
  // Renderer sends: stage-photo://img?u=<encodeURIComponent(photoUrl)>
  protocol.handle("stage-photo", async (request: { url: string }) => {
    const url = new URL(request.url);
    const photoUrl = url.searchParams.get("u");
    if (!photoUrl) {
      return { statusCode: 400, data: "Missing u param", headers: { "Content-Type": "text/plain" } };
    }
    try {
      const decoded = decodeURIComponent(photoUrl);
      const localPath = await getPhotoPath(decoded);
      if (!localPath) {
        return { statusCode: 404, data: "Photo not found", headers: { "Content-Type": "text/plain" } };
      }
      // Return path for direct file streaming — avoids loading into memory.
      return { path: localPath };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error("main", "stage-photo protocol error", { error: msg });
      return { statusCode: 500, data: msg, headers: { "Content-Type": "text/plain" } };
    }
  });

  await setupApplicationMenu();

  // ── Init singletons ──────────────────────────────────────────────────
  await stageController.init();
  await integrationManager.init();

  // Set the remote URL on the controller so StageState.remoteUrl is populated.
  stageController.setRemoteUrl(remoteServer.getLanUrl());

  // Populate the lineup on startup if PCO credentials were already configured
  // (credentials are applied during integrationManager.init above). This fetches
  // the current plan's team members and resolves slots so the display is ready.
  if (stageController.getState().pcoConfigured) {
    try {
      await stageController.refresh();
    } catch (err) {
      logger.error("main", "Startup stage refresh failed", err);
    }
  }

  // Keep the active plan fresh: re-fetch from Planning Center every hour so
  // lineup changes appear automatically without a manual refresh.
  stageController.startAutoRefresh();

  // ── Start services ───────────────────────────────────────────────────
  await remoteServer.start();
  await deviceManager.start();

  openAllDisplayWindows()
    .then(() => {
      const windowCreateEndTime = Date.now();
      logger.info("main", "⏱️ [COLD_START] Display windows opened successfully", {
        timestamp: new Date().toISOString(),
        duration_ms: windowCreateEndTime - windowCreateStartTime,
      });
      // Each display window stays a normal, movable window during setup.
      // Use the green title-bar button or View ▸ Enter Full Screen (⌃⌘F)
      // to send it fullscreen on the target screen when ready.
    })
    .catch((err) => {
      logger.error("main", "Failed to open display windows", err);
    });
});
